def align_active_sprint_boards(apps, schema_editor):
    Sprint = apps.get_model("tasks", "Sprint")
    AgileBoard = apps.get_model("tasks", "AgileBoard")
    ProjectMembership = apps.get_model("projects", "ProjectMembership")
    seen_boards = set()

    for sprint in Sprint.objects.select_related("project", "board").order_by("id"):
        if not sprint.is_active or sprint.is_closed:
            if sprint.board_id:
                Sprint.objects.filter(pk=sprint.pk).update(board=None)
            continue

        if sprint.board_id and sprint.board_id not in seen_boards:
            seen_boards.add(sprint.board_id)
